package com.servicedesk360.websocket;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Configuration; import org.springframework.messaging.simp.config.MessageBrokerRegistry; import org.springframework.messaging.simp.config.ChannelRegistration; import org.springframework.web.socket.config.annotation.*;
@Configuration @EnableWebSocketMessageBroker public class WebSocketConfig implements WebSocketMessageBrokerConfigurer{private final String origin; private final WebSocketAuthInterceptor interceptor; public WebSocketConfig(@Value("${app.cors.allowed-origin:http://localhost:5173}")String origin,WebSocketAuthInterceptor interceptor){this.origin=origin;this.interceptor=interceptor;} @Override public void configureClientInboundChannel(ChannelRegistration r){r.interceptors(interceptor);}
 @Override public void configureMessageBroker(MessageBrokerRegistry r){r.enableSimpleBroker("/topic","/queue");r.setApplicationDestinationPrefixes("/app");r.setUserDestinationPrefix("/user");} @Override public void registerStompEndpoints(StompEndpointRegistry r){r.addEndpoint("/ws").setAllowedOriginPatterns(origin);}}
